"""examples/example.prism is generated by scripts/make_example.py (not saved by Prism).

The expected numbers below are the ones that script computes with scipy 1.18.1 and
statsmodels 0.15.0 (printed at the end of its run); the reader must return them unchanged.
"""
import json
import zipfile
from pathlib import Path

from pytest import approx

import prsmfile
from prsmfile import read_analysis

EXAMPLE = Path(__file__).resolve().parents[1] / "examples" / "example.prism"
REL = 1e-9


def reports():
    with prsmfile.open(EXAMPLE) as pf:
        return {r.analysis.analysis_class: r for r in (read_analysis(pf, a) for a in pf.analyses())}


def section(report, title):
    (s,) = [s for s in report.sections if s.title == title]
    return s


def row(s, name):
    (r,) = [r for r in s.rows if r[0] == name]
    return dict(zip(s.columns, r))


def test_example_is_present_and_synthetic():
    assert EXAMPLE.is_file()
    with zipfile.ZipFile(EXAMPLE) as z:
        doc = json.loads(z.read("document.json"))
    assert doc["createdBy"]["user"] == doc["modifiedBy"]["user"] == "prsmfile-example"
    assert "/" not in json.dumps(doc) and "\\" not in json.dumps(doc)


def test_five_analyses_and_kinds():
    r = reports()
    assert {k: v.kind for k, v in r.items()} == {
        "T_TESTS_AND_NONPARAMETRIC": "structured", "ONE_WAY_ANOVA": "structured",
        "TWO_WAY_ANOVA": "structured", "AREA_UNDER_CURVE": "structured", "NORMALITY_TESTS": "generic"}
    assert all(v.warnings == [] for v in r.values())


def test_welch():
    r = reports()["T_TESTS_AND_NONPARAMETRIC"]
    t = row(section(r, "Test"), "Welch's t test")
    assert t["Statistic"] == approx(1.9287713445677037, rel=REL)
    assert t["df"] == approx(7.818530143393965, rel=REL)
    assert t["P"].value == approx(0.09073667968097265, rel=REL)
    (e,) = section(r, "Effect").rows
    e = dict(zip(section(r, "Effect").columns, e))
    assert e["Difference"] == approx(8.733333333333327, rel=REL)
    assert e["CI lower"] == approx(-1.7504167033113838, rel=REL)
    assert e["CI upper"] == approx(19.217083369978038, rel=REL)
    assert e["n 1"] == e["n 2"] == 6 and e["Difference is"] == "B:Heat treated - A:Control"


def test_oneway_and_tukey():
    r = reports()["ONE_WAY_ANOVA"]
    a = row(section(r, "ANOVA"), "Treatment")
    assert a["F"] == approx(37.10943348659465, rel=REL)
    assert a["P"].value == approx(1.5568944321045764e-06, rel=REL)
    assert (a["df"], a["DFn"], a["DFd"]) == (2, 2, 15)
    assert a["SS"] == approx(5364.564444444447, rel=REL)
    mc = section(r, "Multiple comparisons (Tukey)")
    expected = {"A:Control vs B:Nitrogen low": (-17.300000000000026, 0.008105260944035297),
                "A:Control vs C:Nitrogen high": (-42.06666666666668, 1.041607032625791e-06),
                "B:Nitrogen low vs C:Nitrogen high": (-24.76666666666665, 0.00040143329815178763)}
    assert [x[0] for x in mc.rows] == list(expected)
    for name, (diff, p) in expected.items():
        got = row(mc, name)
        assert got["Mean diff"] == approx(diff, rel=REL)
        assert got["P adjusted"].value == approx(p, rel=REL)


def test_twoway_and_sidak():
    r = reports()["TWO_WAY_ANOVA"]
    anova = section(r, "ANOVA")
    for name, f, p, ss, df in (
            ("Row factor", 34.39064856711902, 1.4896559871594653e-05, 9.500416666666625, 1),
            ("Column factor", 19.01508295625943, 3.6446461466704465e-05, 10.505833333333332, 2),
            ("Interaction", 1.503770739064853, 0.24892899090064982, 0.8308333333333309, 2)):
        got = row(anova, name)
        assert got["F"] == approx(f, rel=REL) and got["P"].value == approx(p, rel=REL)
        assert got["SS"] == approx(ss, rel=REL) and got["df"] == df and got["DFd"] == 18
    res = row(anova, "Residual")
    assert res["SS"] == approx(4.972499999999998, rel=REL) and res["df"] == 18
    mc = section(r, "Multiple comparisons (Bonferroni-Šídák)")
    assert len(mc.rows) == 6
    first = mc.rows[0]
    assert first[0].startswith("row 1:Wild type A:Low light vs") and first[5] == approx(-1.4000000000000004)
    assert first[12].value == approx(0.008439517284637432, rel=REL)
    assert mc.rows[1][12].value == approx(0.00028365668124907817, rel=REL)


def test_auc():
    r = reports()["AREA_UNDER_CURVE"]
    (row_,) = section(r, "Area under curve").rows
    assert row_[2] == approx(1138.2, rel=REL) and row_[4] == 1
    (peak,) = section(r, "Peaks").rows
    assert peak[4] == 0 and peak[5] == 66.5 and peak[6] == approx(1138.2, rel=REL)


def test_generic_reader_shows_shapiro_wilk():
    r = reports()["NORMALITY_TESTS"]
    values = dict((p, v) for p, v in section(r, "Values").rows)
    w = values["samples[A:Control].normalityModel.shapiroWilkTest.W"]
    assert w == approx(0.9023008642166811, rel=REL)
    assert values["samples[A:Control].normalityModel.shapiroWilkTest.pValue"].value == approx(
        0.38770881056144135, rel=REL)


def test_raw_data_tables_are_listed():
    with prsmfile.open(EXAMPLE) as pf:
        tables = [prsmfile.read_table(pf, sid) for sid in pf.data_tables()]
    assert [t.title for t in tables] == ["Lysozyme activity", "Shoot dry mass", "Root length", "Tracer clearance"]
    assert tables[0].columns == ["Control", "Heat treated"] and tables[0].rows[0] == ["41.5", "58.1"]
    assert tables[2].columns[:3] == ["Row title", "Low light 1", "Low light 2"]
